import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';
import { 
  Calendar, Scan, Bell, ChevronLeft, 
  Zap, Image as ImageIcon 
} from 'lucide-react';
import MeetingRoom from './MeetingRoom';
import Transport from './Transport';
import './App.css';

// --- 核心：真实摄像头扫描页面 ---
const ScanPage = () => {
  const navigate = useNavigate();
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);

  // 开启摄像头逻辑
  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: "environment" } // 优先使用后置摄像头
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Please allow camera access to scan.");
    }
  };

  useEffect(() => {
    startCamera();

    // 组件卸载时释放摄像头资源（非常重要！）
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  return (
    <div className="scan-page-container">
      {/* 1. 真实的视频预览层 */}
      <video 
        ref={videoRef} 
        autoPlay 
        playsInline 
        className="camera-video-layer"
      />

      {/* 2. 覆盖在视频上的 UI 层 */}
      <div className="scan-overlay-ui">
        <div className="scan-header">
          <button className="scan-back-btn" onClick={() => navigate(-1)}>
            <ChevronLeft size={28} color="white" />
          </button>
          <span className="scan-title">Scan QR Code</span>
          <button className="scan-action-btn"><Zap size={20} color="white" /></button>
        </div>

        <div className="scan-viewfinder">
          <div className="viewfinder-box">
            <div className="corner top-left"></div>
            <div className="corner top-right"></div>
            <div className="corner bottom-left"></div>
            <div className="corner bottom-right"></div>
            <div className="scan-line"></div>
          </div>
          <p className="scan-tip">Align QR code within the frame to scan</p>
        </div>

        <div className="scan-footer">
          <div className="footer-action">
            <div className="action-icon-circle"><ImageIcon size={24} color="white" /></div>
            <span>Album</span>
          </div>
        </div>
      </div>
    </div>
  );
};

const Home = () => {
  const navigate = useNavigate();
  const menuItems = [
    { label: 'Meeting Room', icon: 'meeting room.png', path: '/meeting-room', badge: '1' },
    { label: 'Transport', icon: 'transportation.png', path: '/transport' },
    { label: 'e-Visitor', icon: 'evisitor.png' },
    { label: 'Ticketing', icon: 'ticketing.png' },
    { label: 'CHART', icon: 'chart.png' },
    { label: 'Wellness', icon: 'wellness.png' },
    { label: 'Meal', icon: 'meal.png' },
    { label: 'Energy', icon: 'energy.png' },
    { label: 'flexHR', icon: 'flexhr.png' },
    { label: 'MyNews', icon: 'mynews.png'  },
    { label: 'Childcare', icon: 'childcare.png'  },
    { label: 'EPP', icon: 'epp.png',  },
  ];

  return (
    <>
      <nav className="welcome-bar">
        <div className="welcome-text">
          <span className="welcome-label">Welcome</span>
          <h2 className="welcome-name">ALAN TAN WAI LOON</h2>
        </div>
        <div className="welcome-icons">
          <div className="icon-wrapper" onClick={() => navigate('/scan')}>
            <Scan size={20} color="white" strokeWidth={2} />
          </div>
          <div className="bell-container">
            <Bell size={20} color="white" strokeWidth={2} />
            <span className="bell-dot"></span> 
          </div>
        </div>
      </nav>

      <header className="hero-header">
        <div className="hero-content">
          <h1>You're in Staging Environment</h1>
        </div>
      </header>

      <div className="warning-container">
        <div className="fixed-calendar-icon"><Calendar size={16} strokeWidth={2.5} /></div>
        <div className="marquee-wrapper">
          <div className="scrolling-text">
            <span>LIVE/PRODUCTION ENVIRONMENT. USE WITH CAUTION. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>
            <span>LIVE/PRODUCTION ENVIRONMENT. USE WITH CAUTION. &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>
          </div>
        </div>
      </div>

      <main className="grid-menu">
        {menuItems.map((item, index) => (
          item.path ? (
            <Link to={item.path} key={index} className="menu-item link-item">
              <div className="icon-container">
                <img src={`/icon_img/${item.icon}`} alt={item.label} />
                {item.badge && <span className="badge">{item.badge}</span>}
              </div>
              <span className="label">{item.label}</span>
            </Link>
          ) : (
            <div key={index} className="menu-item">
              <div className="icon-container">
                <img src={`/icon_img/${item.icon}`} alt={item.label} />
              </div>
              <span className="label">{item.label}</span>
            </div>
          )
        ))}
      </main>
    </>
  );
};

function App() {
  return (
    <Router>
      <div className="mobile-app">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/meeting-room" element={<MeetingRoom />} />
          <Route path="/transport" element={<Transport />} />
          <Route path="/scan" element={<ScanPage />} />
        </Routes>
        <FooterWithConditionalRendering />
      </div>
    </Router>
  );
}

const FooterWithConditionalRendering = () => {
  // 注意：因为在 Router 内部，这里不能直接用 window.location，使用 hook 更好
  // 但为了简化逻辑，我们继续使用这种判断
  const isScanPage = window.location.pathname === '/scan';
  if (isScanPage) return null;

  return (
    <footer className="bottom-nav">
      <Link to="/" className="nav-item active"><img src="/icon_img/home.png" alt="H" /><span>Home</span></Link>
      <div className="nav-item"><img src="/icon_img/dashboard.png" alt="D" /><span>Dashboard</span></div>
      <div className="nav-item"><img src="/icon_img/info.png" alt="I" /><span>Info</span></div>
      <div className="nav-item"><img src="/icon_img/profile.png" alt="P" /><span>Profile</span></div>
    </footer>
  );
};

export default App;
